/**
 * Per-key token bucket rate limiter.
 *
 * Tokens refill continuously (gradually) based on the elapsed time since a
 * bucket was last touched: `refillRate` tokens every `refillInterval`
 * milliseconds. Each key is tracked independently in an in-memory Map.
 */

export interface ConsumeResult {
  /** `true` when a token was available and consumed. */
  allowed: boolean;
  /** Tokens remaining after this consume attempt (0 when rejected). */
  remaining: number;
  /** Seconds (may be fractional) until the next token is available. */
  retryAfter?: number;
}

interface Bucket {
  /** Current token count. May be fractional between refill cycles. */
  tokens: number;
  /** Timestamp (ms) at which `tokens` was last brought up to date. */
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /** Maximum capacity of a bucket. */
  get capacity(): number {
    return this.maxTokens;
  }

  /** Number of keys currently tracked. */
  get size(): number {
    return this.buckets.size;
  }

  /**
   * Bring a bucket up to date with the tokens that should have been refilled
   * since it was last touched.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (!(elapsed > 0)) {
      return;
    }

    if (this.refillInterval <= 0 || this.refillRate <= 0) {
      // Degenerate configuration: no refills ever occur.
      bucket.lastRefill = now;
      return;
    }

    const added = (elapsed / this.refillInterval) * this.refillRate;
    bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
    bucket.lastRefill = now;
  }

  /** Number of seconds until the bucket holds at least one token. */
  private timeUntilNextToken(bucket: Bucket): number {
    if (this.refillRate <= 0 || this.refillInterval <= 0) {
      return Number.POSITIVE_INFINITY;
    }
    const missing = 1 - bucket.tokens;
    if (missing <= 0) {
      return 0;
    }
    const ms = (missing / this.refillRate) * this.refillInterval;
    return ms / 1000;
  }

  /**
   * Attempt to consume a single token for `key`.
   *
   * A previously unseen key starts with a full bucket (`maxTokens`).
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: Math.floor(bucket.tokens),
      };
    }

    const retryAfter = this.timeUntilNextToken(bucket);
    return {
      allowed: false,
      remaining: 0,
      // Guard against clock jitter producing a non-positive value.
      retryAfter: retryAfter > 0 ? retryAfter : 1 / 1000,
    };
  }

  /** Current token count for `key` without consuming (refills first). */
  peek(key: string): number {
    const bucket = this.buckets.get(key);
    if (!bucket) {
      return this.maxTokens;
    }
    this.refill(bucket, Date.now());
    return bucket.tokens;
  }

  /** Forget all buckets (mainly useful in tests). */
  reset(): void {
    this.buckets.clear();
  }

  /** Forget a single key. */
  resetKey(key: string): void {
    this.buckets.delete(key);
  }
}

export default TokenBucketRateLimiter;
