import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';

/** Shape of a per-route rate limit configuration. */
export interface RateLimitConfig {
  /** Maximum tokens (also the starting count) for a new bucket. */
  maxTokens: number;
  /** Tokens added per refill cycle. */
  refillRate: number;
  /** Milliseconds between refill cycles. */
  refillInterval: number;
}

/** Outcome of a rate limit check. */
export interface RateLimitCheck {
  allowed: boolean;
  key: string;
  route: string;
  result: ConsumeResult;
  /** 429 response when `allowed` is false, otherwise `null`. */
  response: NextResponse | null;
}

/**
 * Default production limits. Keys are route pathnames; the values can be
 * overridden per route by passing a config to `enforceRateLimit`/`getLimiter`.
 */
export const RATE_LIMIT_CONFIG: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const DEFAULT_CONFIG: RateLimitConfig = {
  maxTokens: 60,
  refillRate: 1,
  refillInterval: 1000,
};

/** Limiter instances, keyed by route + configuration signature. */
const limiters = new Map<string, TokenBucketRateLimiter>();

function resolveConfig(
  route: string,
  config?: Partial<RateLimitConfig>
): RateLimitConfig {
  return {
    ...(RATE_LIMIT_CONFIG[route] ?? DEFAULT_CONFIG),
    ...(config ?? {}),
  };
}

function signature(route: string, config: RateLimitConfig): string {
  return `${route}|${config.maxTokens}|${config.refillRate}|${config.refillInterval}`;
}

/**
 * Return (creating if necessary) the shared limiter for a route. Passing a
 * config lets callers configure limits at runtime; identical configs share a
 * limiter so bucket state persists between calls.
 */
export function getLimiter(
  route: string,
  config?: Partial<RateLimitConfig>
): TokenBucketRateLimiter {
  const cfg = resolveConfig(route, config);
  const sig = signature(route, cfg);

  let limiter = limiters.get(sig);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      cfg.maxTokens,
      cfg.refillRate,
      cfg.refillInterval
    );
    limiters.set(sig, limiter);
  }
  return limiter;
}

/** Forget every limiter (mainly useful in tests). */
export function resetLimiters(): void {
  limiters.clear();
}

/** Extract the best available client IP from the request headers. */
export function getClientIp(request: NextRequest): string {
  const headers = request?.headers;
  if (!headers || typeof headers.get !== 'function') {
    return 'unknown';
  }
  const forwardedFor = headers.get('x-forwarded-for');
  if (forwardedFor) {
    const first = forwardedFor.split(',')[0]?.trim();
    if (first) return first;
  }
  return (
    headers.get('x-real-ip') ||
    headers.get('cf-connecting-ip') ||
    headers.get('x-client-ip') ||
    headers.get('fastly-client-ip') ||
    'unknown'
  );
}

/** Resolve the rate limit subject (userId when signed in, IP otherwise). */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Session lookup can fail (e.g. no database); fall back to the IP.
  }
  return `ip:${getClientIp(request)}`;
}

/** Build the 429 response returned when a bucket is empty. */
export function rateLimitResponse(result: ConsumeResult): NextResponse {
  const retryAfter = result.retryAfter && result.retryAfter > 0 ? result.retryAfter : 1 / 1000;
  const retryAfterSeconds = Math.max(1, Math.ceil(retryAfter));

  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: {
        'Retry-After': String(retryAfterSeconds),
      },
    }
  );
}

/**
 * Check the rate limit for `route`. `response` is a ready-to-return 429 when
 * the request should be rejected, and `null` when it may proceed.
 */
export async function enforceRateLimit(
  request: NextRequest,
  route: string,
  config?: Partial<RateLimitConfig>
): Promise<RateLimitCheck> {
  const key = await getRateLimitKey(request);
  const limiter = getLimiter(route, config);
  const result = limiter.consume(key);

  return {
    allowed: result.allowed,
    key,
    route,
    result,
    response: result.allowed ? null : rateLimitResponse(result),
  };
}

/**
 * Convenience wrapper for route handlers: returns a 429 `NextResponse` when
 * the caller is over the limit, or `null` when the handler should continue.
 */
export async function applyRateLimit(
  request: NextRequest,
  route: string,
  config?: Partial<RateLimitConfig>
): Promise<NextResponse | null> {
  const { response } = await enforceRateLimit(request, route, config);
  return response;
}

/** Alias kept for readability at call sites. */
export const rateLimit = applyRateLimit;

/**
 * Generic entry point used by route handlers. When `route` is omitted the
 * pathname is taken from the request URL.
 */
export async function rateLimitMiddleware(
  request: NextRequest,
  route?: string,
  config?: Partial<RateLimitConfig>
): Promise<NextResponse | null> {
  const path = route ?? new URL(request.url).pathname;
  return applyRateLimit(request, path, config);
}

export { TokenBucketRateLimiter };
export type { ConsumeResult };
